//#region src/milky/transform/message/outgoing.ts
async function transformOutgoingMessage(ctx, segments, peerUid, isGroup, isInsideForward) {
	const elements = [];
	const deleteAfterSentFiles = [];
	for (const segment of segments) try {
		if (segment.type === "text") elements.push(SendElement.text(segment.data.text));
		else if (segment.type === "mention" && isGroup) {
			const memberUin = segment.data.user_id;
			const info = await ctx.ntGroupApi.getGroupMemberByUin(+peerUid, memberUin, false);
			elements.push(SendElement.at(memberUin, AtType.One, `@${info?.cardName || info?.nick || ""}`));
		} else if (segment.type === "mention_all" && isGroup) elements.push(SendElement.at(0, AtType.All, "@全体成员"));
		else if (segment.type === "face") elements.push(SendElement.face(+segment.data.face_id, segment.data.is_large ? 3 : void 0));
		else if (segment.type === "reply") {
			const peer = {
				chatType: isGroup ? 2 : 1,
				peerUid,
				guildId: ""
			};
			let msg = ctx.store.getMsgBySeq(peer.peerUid, segment.data.message_seq);
			let srcMsg;
			if (!msg) {
				const { msgList, msgByteList } = await ctx.ntMsgApi.getSingleMsg(peer, segment.data.message_seq);
				msg = msgList[0];
				if (isInsideForward) srcMsg = msgByteList[0];
			}
			if (!msg) throw new Error("被回复的消息未找到");
			if (isInsideForward && !srcMsg) {
				const { msgByteList } = await ctx.ntMsgApi.getSingleMsg(peer, segment.data.message_seq);
				srcMsg = msgByteList[0];
			}
			elements.push(SendElement.reply(segment.data.message_seq, msg.senderUin, msg.senderUid, msg.msgTime, msg.clientSeq, srcMsg));
		} else if (segment.type === "image") {
			const imageBuffer = await resolveMilkyUri(segment.data.uri);
			const tempPath = path.join(TEMP_DIR, `image-${randomUUID()}`);
			await writeFile(tempPath, imageBuffer);
			const subType = segment.data.sub_type === "sticker" ? 1 : 0;
			const picElement = await SendElement.pic(ctx, tempPath, segment.data.summary ?? "", subType);
			elements.push(picElement);
			deleteAfterSentFiles.push(tempPath);
		} else if (segment.type === "record") {
			const recordBuffer = await resolveMilkyUri(segment.data.uri);
			const tempPath = path.join(TEMP_DIR, `audio-${randomUUID()}`);
			await writeFile(tempPath, recordBuffer);
			const pttElement = await SendElement.ptt(ctx, tempPath);
			elements.push(pttElement);
			deleteAfterSentFiles.push(tempPath);
		} else if (segment.type === "video") {
			const videoBuffer = await resolveMilkyUri(segment.data.uri);
			const tempPath = path.join(TEMP_DIR, `video-${randomUUID()}`);
			await writeFile(tempPath, videoBuffer);
			let thumbTempPath = void 0;
			if (segment.data.thumb_uri) {
				const thumbBuffer = await resolveMilkyUri(segment.data.thumb_uri);
				thumbTempPath = path.join(TEMP_DIR, `thumb-${randomUUID()}`);
				await writeFile(thumbTempPath, thumbBuffer);
				deleteAfterSentFiles.push(thumbTempPath);
			}
			const videoElement = await SendElement.video(ctx, tempPath, thumbTempPath);
			elements.push(videoElement);
			deleteAfterSentFiles.push(tempPath);
		} else if (segment.type === "forward") {
			const { data } = segment;
			const nodes = [];
			for (const item of data.messages) {
				const res = await transformOutgoingMessage(ctx, item.segments, peerUid, isGroup, true);
				deleteAfterSentFiles.push(...res.deleteAfterSentFiles);
				nodes.push({
					senderUin: item.user_id,
					senderName: item.sender_name,
					elements: res.elements,
					msgTime: item.time ?? void 0
				});
			}
			elements.push(SendElement.forward(nodes, data.title, data.preview, data.summary, data.prompt));
		} else if (segment.type === "light_app") {
			const arkElement = SendElement.ark(segment.data.json_payload);
			elements.push(arkElement);
		}
	} catch (error) {
		ctx.logger.error("MilkyTransform", `Failed to transform segment ${segment.type}: ${error}`);
	}
	return {
		elements,
		deleteAfterSentFiles
	};
}
//#endregion
//#region src/milky/transform/message/incoming.ts
async function transformIncomingPrivateMessage(ctx, friend, message) {
	return {
		message_scene: "friend",
		peer_id: +message.peerUin,
		message_seq: +message.msgSeq,
		sender_id: +message.senderUin,
		time: +message.msgTime,
		segments: await transformIncomingSegments(ctx, message),
		friend: transformFriend(friend)
	};
}
async function transformIncomingGroupMessage(ctx, group, member, message) {
	return {
		message_scene: "group",
		peer_id: +message.peerUin,
		message_seq: +message.msgSeq,
		sender_id: +message.senderUin,
		time: +message.msgTime,
		segments: await transformIncomingSegments(ctx, message),
		group: transformGroup(group),
		group_member: transformGroupMember(member, +group.groupCode)
	};
}
async function transformIncomingTempMessage(ctx, group, message) {
	return {
		message_scene: "temp",
		peer_id: +message.peerUin,
		message_seq: +message.msgSeq,
		sender_id: +message.senderUin,
		time: +message.msgTime,
		segments: await transformIncomingSegments(ctx, message),
		group: transformGroup(group)
	};
}
async function transformIncomingSegments(ctx, message) {
	const segments = [];
	for (const element of message.elements) switch (element.elementType) {
		case ElementType.Text:
			if (element.textElement?.atType === AtType.All) segments.push({
				type: "mention_all",
				data: {}
			});
			else if (element.textElement?.atType === AtType.One) segments.push({
				type: "mention",
				data: {
					user_id: element.textElement.atUin,
					name: element.textElement.content.slice(1)
				}
			});
			else if (element.textElement?.content) segments.push({
				type: "text",
				data: { text: element.textElement.content }
			});
			break;
		case ElementType.Face:
			segments.push({
				type: "face",
				data: {
					face_id: element.faceElement.faceIndex.toString(),
					is_large: element.faceElement.faceType === 3
				}
			});
			break;
		case ElementType.Reply: {
			const { replyMsgSeq, senderUin, replyMsgTime, replyMsgClientSeq } = element.replyElement;
			const peer = {
				chatType: message.chatType,
				peerUid: message.peerUid
			};
			let msg = ctx.store.getMsgBySeq(message.peerUid, replyMsgSeq);
			if (!msg) {
				const { msgList } = await ctx.ntMsgApi.getSingleMsg(peer, replyMsgSeq);
				msg = msgList[0];
			}
			if (!msg && peer.chatType !== ChatType.Group) {
				const { msgList } = await ctx.ntMsgApi.getC2CMsgsByTimeAndCount(peer, replyMsgTime + 1, 3, false);
				msg = msgList.find((e) => e.clientSeq === replyMsgClientSeq);
			}
			segments.push({
				type: "reply",
				data: {
					message_seq: replyMsgSeq,
					sender_id: senderUin,
					time: replyMsgTime,
					segments: msg ? await transformIncomingSegments(ctx, msg) : []
				}
			});
			break;
		}
		case ElementType.Pic:
			segments.push({
				type: "image",
				data: {
					resource_id: element.picElement.fileUuid,
					temp_url: await ctx.ntFileApi.getImageUrl(element.picElement.originImageUrl, element.picElement.md5HexStr),
					width: element.picElement.picWidth,
					height: element.picElement.picHeight,
					summary: element.picElement.summary || "[图片]",
					sub_type: element.picElement.picSubType === 1 ? "sticker" : "normal"
				}
			});
			break;
		case ElementType.Ptt:
			segments.push({
				type: "record",
				data: {
					resource_id: element.pttElement.fileUuid,
					temp_url: await ctx.ntFileApi.getPttUrl(element.pttElement.fileUuid, message.chatType === 2),
					duration: element.pttElement.duration
				}
			});
			break;
		case ElementType.Video:
			segments.push({
				type: "video",
				data: {
					resource_id: element.videoElement.fileUuid,
					temp_url: await ctx.ntFileApi.getVideoUrl(element.videoElement.fileUuid, message.chatType === ChatType.Group),
					width: element.videoElement.thumbWidth,
					height: element.videoElement.thumbHeight,
					duration: element.videoElement.fileTime
				}
			});
			break;
		case ElementType.File:
			segments.push({
				type: "file",
				data: {
					file_id: element.fileElement.fileUuid,
					file_name: element.fileElement.fileName,
					file_size: +element.fileElement.fileSize
				}
			});
			break;
		case ElementType.MultiForward: {
			const content = new XMLParser().parse(element.multiForwardMsgElement.xmlContent);
			segments.push({
				type: "forward",
				data: {
					forward_id: element.multiForwardMsgElement.resId,
					title: content.msg.item.title[0],
					preview: content.msg.item.title.slice(1),
					summary: content.msg.item.summary
				}
			});
			break;
		}
		case ElementType.MarketFace:
			segments.push({
				type: "market_face",
				data: {
					emoji_package_id: element.marketFaceElement.emojiPackageId,
					emoji_id: element.marketFaceElement.emojiId,
					key: element.marketFaceElement.key,
					summary: element.marketFaceElement.faceName,
					url: `https://gxh.vip.qq.com/club/item/parcel/item/${element.marketFaceElement.emojiId.substring(0, 2)}/${element.marketFaceElement.emojiId}/raw300.gif`
				}
			});
			break;
		case ElementType.Ark: {
			const { arkElement } = element;
			const match = arkElement.bytesData.match(/"app"\s*:\s*"([^"]*)"/);
			if (match?.[1]) if (match[1] === "com.tencent.multimsg") {
				const data = JSON.parse(arkElement.bytesData);
				segments.push({
					type: "forward",
					data: {
						forward_id: data.meta.detail.resid,
						title: data.meta.detail.source,
						preview: data.meta.detail.news.map((item) => item.text),
						summary: data.meta.detail.summary
					}
				});
			} else segments.push({
				type: "light_app",
				data: {
					app_name: match[1],
					json_payload: arkElement.bytesData
				}
			});
			break;
		}
		case ElementType.Markdown:
			segments.push({
				type: "markdown",
				data: { content: element.markdownElement.content }
			});
			break;
	}
	return segments;
}
async function transformIncomingForwardedMessage(ctx, message) {
	return {
		message_seq: message.msgSeq,
		sender_name: message.sendNickName,
		avatar_url: message.forwardAvatar,
		time: message.msgTime,
		segments: await transformIncomingSegments(ctx, message)
	};
}
