/**
* Transform NTQQ message-created event to Milky message_receive event (private)
*/
async function transformPrivateMessageCreated(ctx, message) {
	try {
		const transformedMessage = await transformIncomingPrivateMessage(ctx, await ctx.ntFriendApi.getFriendByUid(message.senderUid, false), message);
		if (transformedMessage.segments.length === 0) return null;
		return transformedMessage;
	} catch (error) {
		ctx.logger.error("Failed to transform private message created event:", error);
		return null;
	}
}
/**
* Transform NTQQ message-created event to Milky message_receive event (group)
*/
async function transformGroupMessageCreated(ctx, message) {
	try {
		const transformedMessage = await transformIncomingGroupMessage(ctx, await ctx.ntGroupApi.getGroup(+message.peerUid, false), await ctx.ntGroupApi.getGroupMemberByUid(+message.peerUin, message.senderUid, false), message);
		if (transformedMessage.segments.length === 0) return null;
		return transformedMessage;
	} catch (error) {
		ctx.logger.error("Failed to transform group message created event:", error);
		return null;
	}
}
