		ctx.on("nt/group-removed", () => {
			if (this.groupsCache.length > 0) this.getGroups(true);
		});
		ctx.on("nt/group-member-added", (data) => {
			if (this.membersCache.has(data.groupCode)) this.getGroupMembers(data.groupCode, true);
		});
