//#region src/ntqqapi/helper/messageBuilding.ts
var MessageBuilding = class MessageBuilding {
	ctx;
	inputElems;
	outputElems;
	chatType;
	peerUid;
	nestedForwardTrace;
	content;
	constructor(ctx, elements, chatType, peerUid, nestedForwardTrace = /* @__PURE__ */ new Map()) {
		this.ctx = ctx;
		this.inputElems = elements;
		this.outputElems = [];
		this.chatType = chatType;
		this.peerUid = peerUid;
		this.nestedForwardTrace = nestedForwardTrace;
	}
	async [ElementType.Text](data) {
		const { textElement } = data;
		if (textElement.atType === 1) {
			const attr6 = Buffer.from([
				0,
				1,
				0,
				0,
				0,
				5,
				1,
				0,
				0,
				0,
				0,
				0,
				0
			]);
			this.outputElems.push({ text: {
				str: textElement.content,
				attr6Buf: attr6
			} });
		} else if (textElement.atType === 2) {
			const attr6Buf = Buffer.alloc(20);
			attr6Buf.writeUInt16BE(1, 0);
			attr6Buf.writeUInt16BE(0, 2);
			attr6Buf.writeUInt16BE(textElement.content.length, 4);
			attr6Buf.writeUInt8(0, 6);
			attr6Buf.writeUInt32BE(textElement.atUin, 7);
			attr6Buf.writeUInt16BE(0, 11);
			this.outputElems.push({ text: {
				str: textElement.content,
				attr6Buf
			} });
		} else this.outputElems.push({ text: { str: textElement.content } });
	}
	async [ElementType.Face](data) {
		const { faceElement } = data;
		if (faceElement.faceType === 5) {
			const f = faceElement;
			const pbElem = Msg.PokeExtra.encode({ type: f.faceIndex });
			this.outputElems.push({ commonElem: {
				serviceType: 2,
				pbElem,
				businessType: f.faceIndex
			} });
		} else if (faceElement.faceType === 3) {
			const f = faceElement;
			const pbElem = Msg.LargeFaceExtra.encode({
				aniStickerPackId: f.packId ? String(f.packId) : "1",
				aniStickerId: String(f.stickerId),
				faceId: faceElement.faceIndex,
				aniStickerType: f.stickerType ?? 2,
				resultId: f.resultId ? +f.resultId : void 0
			});
			this.outputElems.push({ commonElem: {
				serviceType: 37,
				pbElem,
				businessType: f.stickerType ?? 1
			} });
		} else if (faceElement.faceType === 2) {
			const f = faceElement;
			const pbElem = Msg.QSmallFaceExtra.encode({
				faceId: f.faceIndex,
				text: f.faceText,
				compatText: f.faceText
			});
			this.outputElems.push({ commonElem: {
				serviceType: 33,
				pbElem,
				businessType: f.stickerType ?? 1
			} });
		} else this.outputElems.push({ face: { index: faceElement.faceIndex } });
	}
	async [ElementType.MarketFace](data) {
		const { marketFaceElement } = data;
		this.outputElems.push({ marketFace: {
			summary: marketFaceElement.faceName,
			itemType: 6,
			info: 1,
			faceId: Buffer.from(marketFaceElement.emojiId, "hex"),
			tabId: marketFaceElement.emojiPackageId,
			subType: 3,
			key: marketFaceElement.key,
			width: marketFaceElement.imageWidth,
			height: marketFaceElement.imageHeight
		} });
	}
	async [ElementType.Reply](data) {
		const { replyElement } = data;
		/**let elems
		if (replyElement.elements.length > 0) {
		// 把锚点的 elements 转成简化的 text Msg.Elem 列表内联进 srcMsg.elems。
		// 复杂段（image/video/face/...）退化成占位文本，至少让 client 渲染时
		// 不再显示 "[原消息已过期]" —— 跟 server 端对 mention 段做的归一化是一样的思路。
		const elemBytes = []
		for (const el of replyElement.elements) {
		let str, face
		if (el.elementType === ElementType.Text) {
		str = el.textElement!.content
		} else if (el.elementType === ElementType.Pic) {
		str = el.picElement!.summary || '[图片]'
		} else if (el.elementType === ElementType.Video) {
		str = '[视频]'
		} else if (el.elementType === ElementType.Ptt) {
		str = '[语音]'
		} else if (el.elementType === ElementType.Face) {
		const { faceType, faceIndex, faceText } = el.faceElement!
		if (faceType === FaceType.Old || faceType === FaceType.Normal) {
		face = faceIndex
		} else {
		str = faceText
		}
		} else if (el.elementType === ElementType.MarketFace) {
		str = el.marketFaceElement!.faceName
		} else if (el.elementType === ElementType.Ark) {
		const match = el.arkElement!.bytesData!.match(/"prompt"\s*:\s*"([^"]*)"/)
		str = match?.[1] ?? ''
		} else if (el.elementType === ElementType.MultiForward) {
		str = '[合并转发]'
		}
		if (str !== undefined) {
		elemBytes.push(Msg.Elem.encode({ text: { str } }))
		} else if (face !== undefined) {
		elemBytes.push(Msg.Elem.encode({ face: { index: face } }))
		}
		}
		if (elemBytes.length > 0) {
		elems = elemBytes
		}
		}*/
		this.outputElems.push({ srcMsg: {
			origSeqs: [replyElement.replyMsgClientSeq || replyElement.replyMsgSeq],
			senderUin: replyElement.senderUin,
			time: replyElement.replyMsgTime,
			attr: {
				senderUid: replyElement.senderUid,
				ntMsgSeq: replyElement.replyMsgClientSeq ? replyElement.replyMsgSeq : void 0
			},
			srcMsg: replyElement.srcMsg
		} });
		if (this.chatType === ChatType.Group) {
			const attr6Buf = Buffer.alloc(20);
			attr6Buf.writeUInt16BE(1, 0);
			attr6Buf.writeUInt16BE(0, 2);
			attr6Buf.writeUInt16BE(1, 4);
			attr6Buf.writeUInt8(0, 6);
			attr6Buf.writeUInt32BE(replyElement.senderUin, 7);
			attr6Buf.writeUInt16BE(0, 11);
			const pbReserve = Msg.TextResvAttr.encode({
				atType: 2,
				atMemberUin: 0,
				atMemberUid: replyElement.senderUid
			});
			this.outputElems.push({ text: {
				str: "@",
				attr6Buf,
				pbReserve
			} }, { text: { str: " " } });
		}
	}
	async [ElementType.Pic](data) {
		const { picElement: p } = data;
		const isGroup = this.chatType === ChatType.Group;
		const result = isGroup ? await this.ctx.ntFileApi.uploadGroupImage(this.peerUid, p.sourcePath, p.picWidth, p.picHeight, p.summary, p.picSubType) : await this.ctx.ntFileApi.uploadPrivateImage(this.chatType, this.peerUid, p.sourcePath, p.picWidth, p.picHeight, p.summary, p.picSubType);
		this.outputElems.push({ commonElem: {
			serviceType: 48,
			pbElem: result.msgInfo,
			businessType: isGroup ? 20 : 10
		} });
	}
	async [ElementType.Video](data) {
		const { videoElement: v } = data;
		const isGroup = this.chatType === ChatType.Group;
		const result = isGroup ? await this.ctx.ntFileApi.uploadGroupVideo(this.peerUid, v.filePath, v.thumbPath, v.fileTime, v.thumbWidth, v.thumbHeight) : await this.ctx.ntFileApi.uploadPrivateVideo(this.chatType, this.peerUid, v.filePath, v.thumbPath, v.fileTime, v.thumbWidth, v.thumbHeight);
		this.outputElems.push({ commonElem: {
			serviceType: 48,
			pbElem: result.msgInfo,
			businessType: isGroup ? 21 : 11
		} });
	}
	async [ElementType.Ptt](data) {
		const { pttElement: p } = data;
		const isGroup = this.chatType === ChatType.Group;
		const result = isGroup ? await this.ctx.ntFileApi.uploadGroupPtt(this.peerUid, p.filePath, p.duration) : await this.ctx.ntFileApi.uploadPrivatePtt(this.chatType, this.peerUid, p.filePath, p.duration);
		this.outputElems.push({ commonElem: {
			serviceType: 48,
			pbElem: result.msgInfo,
			businessType: isGroup ? 22 : 12
		} });
	}
	async [ElementType.Ark](data) {
		const { arkElement } = data;
		this.outputElems.push({ lightApp: { data: Buffer.concat([Buffer.from([1]), deflateSync(Buffer.from(arkElement.bytesData, "utf-8"))]) } });
	}
	async [ElementType.MultiForward](data) {
		const { multiForwardMsgElement } = data;
		const messages = [];
		let seq = Math.trunc(Math.random() * 65430);
		const preview = multiForwardMsgElement.preview ?? [];
		const needGeneratePreview = preview.length === 0;
		const isGroup = this.chatType === ChatType.Group;
		for (const node of multiForwardMsgElement.nodes) {
			if (needGeneratePreview && preview.length < 4) {
				const content = node.elements.reduce((acc, curr) => {
					let preview;
					if (curr.elementType === ElementType.Text) preview = curr.textElement.content.slice(0, 70);
					else if (curr.elementType === ElementType.Face) preview = curr.faceElement.faceText;
					else if (curr.elementType === ElementType.MarketFace) preview = curr.marketFaceElement.faceName;
					else if (curr.elementType === ElementType.Pic) preview = curr.picElement.summary || "[图片]";
					else if (curr.elementType === ElementType.Video) preview = "[视频]";
					else if (curr.elementType === ElementType.Ptt) preview = "[语音]";
					else if (curr.elementType === ElementType.Ark) preview = curr.arkElement.bytesData.match(/"prompt"\s*:\s*"([^"]*)"/)?.[1] ?? "";
					else if (curr.elementType === ElementType.MultiForward) preview = "[合并转发]";
					else if (curr.elementType === ElementType.Reply) preview = "";
					return acc + preview;
				}, "");
				preview.push(`${node.senderName}: ${content}`);
			}
			const { elems, content } = await new MessageBuilding(this.ctx, node.elements, this.chatType, this.peerUid, this.nestedForwardTrace).build();
			messages.push({
				routingHead: {
					fromUin: node.senderUin,
					c2c: isGroup ? void 0 : { name: node.senderName },
					group: isGroup ? {
						groupCode: 284840486,
						groupCard: node.senderName,
						groupCardType: 2
					} : void 0
				},
				contentHead: {
					msgType: isGroup ? 82 : 9,
					random: Math.floor(Math.random() * 4294967290),
					groupMsgSeqOrC2cClientSeq: seq,
					msgTime: node.msgTime ?? Math.trunc(Date.now() / 1e3),
					pkgNum: 1,
					pkgIndex: 0,
					divSeq: 0,
					forward: {
						field1: 0,
						field2: 0,
						field3: 0,
						field4: "",
						avatar: ""
					}
				},
				body: {
					richText: { elems },
					msgContent: content
				}
			});
			seq++;
		}
		const items = [{
			fileName: "MultiMsg",
			buffer: { msg: messages }
		}];
		for (const [key, value] of this.nestedForwardTrace) items.push({
			fileName: key,
			buffer: { msg: value }
		});
		const resid = await this.ctx.ntMsgApi.uploadForwardMsgs(this.peerUid, isGroup, items);
		const id = crypto.randomUUID();
		this.nestedForwardTrace.set(id, messages);
		const prompt = multiForwardMsgElement.prompt ?? "[聊天记录]";
		const content = JSON.stringify({
			app: "com.tencent.multimsg",
			config: {
				autosize: 1,
				forward: 1,
				round: 1,
				type: "normal",
				width: 300
			},
			desc: prompt,
			extra: JSON.stringify({
				filename: id,
				tsum: 0
			}),
			meta: { detail: {
				news: preview.map((e) => ({ text: e })),
				resid,
				source: multiForwardMsgElement.title ?? isGroup ? "群聊的聊天记录" : "聊天记录",
				summary: multiForwardMsgElement.summary ?? `查看${multiForwardMsgElement.nodes.length}条转发消息`,
				uniseq: id
			} },
			prompt,
			ver: "0.0.0.5",
			view: "contact"
		});
		this.outputElems.push({ lightApp: { data: Buffer.concat([Buffer.from([1]), deflateSync(Buffer.from(content, "utf-8"))]) } });
	}
	async [ElementType.File](data) {
		const fileName = data.fileElement.fileName;
		if (this.chatType === ChatType.Group) {
			const uploaded = await this.ctx.ntFileApi.uploadGroupFile(+this.peerUid, data.fileElement.filePath, fileName);
			const extra = Msg.GroupFileExtra.encode({
				field1: 6,
				fileName,
				inner: { info: {
					busId: 102,
					fileId: uploaded.fileId,
					fileSize: uploaded.fileSize,
					fileName,
					fileMd5: uploaded.fileMd5
				} }
			});
			const lenBuf = Buffer.alloc(2);
			lenBuf.writeUInt16BE(extra.length);
			this.outputElems.push({ transElemInfo: {
				elemType: 24,
				elemValue: Buffer.concat([
					Buffer.from([1]),
					lenBuf,
					extra
				])
			} });
		} else {
			const uploaded = await this.ctx.ntFileApi.uploadPrivateFile(this.chatType, this.peerUid, data.fileElement.filePath, fileName);
			const extra = Msg.FileExtra.encode({ file: {
				fileType: 0,
				fileUuid: uploaded.fileId,
				fileMd5: uploaded.file10MMd5,
				fileName,
				fileSize: uploaded.fileSize,
				subCmd: 1,
				dangerLevel: 0,
				expireTime: Math.floor(Date.now() / 1e3 + 10080 * 60),
				fileIdCrcMedia: uploaded.crcMedia
			} });
			this.content = extra;
		}
	}
	async build() {
		for (const element of this.inputElems) await this[element.elementType].call(this, element);
		return {
			elems: this.outputElems,
			content: this.content
		};
	}
};
