//#region src/ntqqapi/api/msg.ts
var NTMsgApi = class extends Service {
	ctx;
	static inject = [
		"ntUserApi",
		"qqProtocol",
		"store",
		"ntFileApi"
	];
	constructor(ctx) {
		super(ctx, "ntMsgApi");
		this.ctx = ctx;
	}
	async setGroupMsgReaction(groupCode, msgSeq, emojiId, setEmoji, emojiType) {
		return await this.ctx.qqProtocol.setGroupReaction(groupCode, msgSeq, emojiId, setEmoji, emojiType);
	}
	async getMsgReactionList(peer, msgSeq, emojiId, count, cookie) {
		return await this.ctx.qqProtocol.fetchMsgEmojiLikes(+peer.peerUid, msgSeq, emojiId, count, cookie);
	}
	async recallMsg(peer, msgSeq, clientSeq, msgRandom, msgTime) {
		if (peer.chatType === ChatType.Group) await this.ctx.qqProtocol.recallGroupMessage(+peer.peerUid, msgSeq);
		else await this.ctx.qqProtocol.recallC2CMessage(peer.peerUid, clientSeq, msgRandom, msgTime, msgSeq);
	}
	/**
	* 挂一次性 listener 等 OlPush 推回我们刚发出去那条消息的回声。
	* 用 (peerUid, msgRandom) 匹配——random 是发送方在 PbSendMsg 里自己造、server 原样
	* 广播给所有人的 32-bit 值，两端唯一可靠对得上的字段。msgSeq 偶尔会差 1-N 个槽。
	*/
	waitForSelfEcho(peer, random, timeoutMs) {
		return new Promise((resolve, reject) => {
			const dispose = this.ctx.on("nt/message-sent", (data) => {
				const msg = data.message;
				if (msg.peerUid !== peer.peerUid) return;
				if (+msg.msgRandom !== random) return;
				clearTimeout(timer);
				dispose();
				resolve(msg);
			});
			const timer = setTimeout(() => {
				dispose();
				reject(/* @__PURE__ */ new Error("waitForSelfEcho timeout"));
			}, timeoutMs);
		});
	}
	/**
	* C2C 发完 PbSendMsg 后用 SsoGetRoamMsg 反查刚发的那条，拿真 msgSeq + msgUid。
	* 匹配条件：random 一致 + msgTime 跟 PbSendMsgResp.sendTime 同秒附近（防同 random 撞）。
	* 加重试是因为 server 入库 c2c 历史流稍滞后（~50-200ms）。
	*/
	async sendMsg(peer, msgElements) {
		let chatType = peer.chatType;
		let groupCode;
		if (peer.chatType === ChatType.Group) groupCode = +peer.peerUid;
		else if (peer.chatType === ChatType.TempC2CFromGroup) {
			const tempChatInfo = await this.ctx.store.getTempChatInfo(peer.peerUid);
			if (tempChatInfo) groupCode = tempChatInfo.groupCode;
			else chatType = ChatType.C2C;
		}
		const { elems, content } = await new MessageBuilding(this.ctx, msgElements, chatType, peer.peerUid).build();
		const random = randomBytes(4).readUInt32BE(0);
		const echoP = chatType === ChatType.Group ? this.waitForSelfEcho(peer, random, 1e4) : null;
		echoP?.catch(() => {});
		const fileElem = elems.find((e) => e.transElemInfo?.elemType === 24);
		if (fileElem) {
			const buf = fileElem.transElemInfo.elemValue.subarray(3);
			const extra = Msg.GroupFileExtra.decode(buf);
			const ret = await this.ctx.qqProtocol.feedGroupFile(groupCode, extra.inner.info.fileId, random);
			if (ret.feedsInfoRsp.retCode !== 0n) throw new Error(`发送文件失败 (code=${ret.feedsInfoRsp.retCode}): ${ret.feedsInfoRsp.clientWording}`);
			return await echoP;
		}
		const ret = await this.ctx.qqProtocol.sendMessage({
			chatType,
			groupCode,
			toUid: chatType !== ChatType.Group ? peer.peerUid : void 0,
			elems,
			random,
			content
		});
		if (ret.resultCode !== 0) throw new Error(`发送消息失败 (code=${ret.resultCode}): ${ret.errMsg}`);
		return (echoP ? await echoP : void 0) ?? {
			msgId: (16777216n << 32n | BigInt(ret.random)).toString(),
			msgTime: ret.timestamp,
			msgSeq: ret.sequence,
			msgRandom: ret.random,
			senderUid: selfInfo.uid,
			senderUin: +selfInfo.uin,
			peerUid: peer.peerUid,
			peerUin: chatType === ChatType.Group ? +peer.peerUid : await this.ctx.ntUserApi.getUinByUid(peer.peerUid),
			sendNickName: "",
			sendMemberName: "",
			chatType,
			elements: parseElements(elems, chatType === ChatType.Group),
			peerName: "",
			tempFromGroupCode: chatType === ChatType.TempC2CFromGroup ? groupCode : 0,
			clientSeq: ret.clientSequence,
			forwardAvatar: ""
		};
	}
	async getSingleMsg(peer, msgSeq) {
		let retcode, errorMsg, messages;
		if (peer.chatType === ChatType.Group) {
			const res = await this.ctx.qqProtocol.getGroupMessages(+peer.peerUid, msgSeq, msgSeq);
			retcode = res.retcode;
			errorMsg = res.errorMsg;
			messages = res.body.messages;
		} else {
			const res = await this.ctx.qqProtocol.getC2CMessages(peer.peerUid, msgSeq, msgSeq);
			retcode = res.retcode;
			errorMsg = res.errorMsg;
			messages = res.messages;
		}
		return {
			retcode,
			errorMsg,
			msgList: filterNullable(messages.map((e) => convertToRawMessage(Msg.Message.decode(e)))),
			msgByteList: messages
		};
	}
	/** 一次最多拉取 30 条消息 */
	async getMsgsBySeqAndCount(peer, msgSeq, cnt, queryOrder) {
		const startSeq = queryOrder ? msgSeq : Math.max(1, msgSeq - cnt + 1);
		const endSeq = queryOrder ? msgSeq + cnt - 1 : msgSeq;
		let retcode, errorMsg, messages;
		if (peer.chatType === ChatType.Group) {
			const res = await this.ctx.qqProtocol.getGroupMessages(+peer.peerUid, startSeq, endSeq);
			retcode = res.retcode;
			errorMsg = res.errorMsg;
			messages = res.body.messages;
		} else {
			const res = await this.ctx.qqProtocol.getC2CMessages(peer.peerUid, startSeq, endSeq);
			retcode = res.retcode;
			errorMsg = res.errorMsg;
			messages = res.messages;
		}
		return {
			retcode,
			errorMsg,
			msgList: filterNullable(messages.map((e) => convertToRawMessage(Msg.Message.decode(e)))),
			msgByteList: messages
		};
	}
	async getC2CMsgsByTimeAndCount(peer, msgTime, cnt, queryOrder) {
		const res = await this.ctx.qqProtocol.getC2CRoamMessages(peer.peerUid, msgTime, cnt, queryOrder ? 2 : 1);
		return {
			msgList: filterNullable(res.messages.map((e) => convertToRawMessage(Msg.Message.decode(e)))),
			msgByteList: res.messages
		};
	}
	async setMsgRead(peer, startSeq) {
		return await this.ctx.qqProtocol.reportMessageRead(peer.chatType, peer.peerUid, startSeq);
	}
	async getCustomFaceList() {
		const resp = await this.ctx.qqProtocol.listFavEmojis();
		const ui = resp.userInfo;
		const bid = ui.bid || "qq_expression";
		const uin = selfInfo.uin;
		const emojiInfoList = ui.fileName.map((emojiId) => ({
			emojiId,
			url: `https://p.qpic.cn/${bid}/${uin}/${emojiId}/0`
		}));
		return {
			retCode: resp.retCode,
			errMsg: resp.errMsg,
			emojiInfoList
		};
	}
	async addCustomFace(emojiPath) {
		const stat = await promises.stat(emojiPath);
		const md5 = await getMd5BufferFromFile(emojiPath);
		const body = (await this.ctx.qqProtocol.addFavEmojiPrep({
			md5,
			fileSize: stat.size
		})).body;
		if (!body || body.retCode !== 0) return {
			retCode: body?.retCode ?? -1,
			errMsg: "",
			emojiId: ""
		};
		const emojiId = body.ext?.emojiId || "";
		if (!body.uKey || body.uKey.length === 0) return {
			retCode: 0,
			errMsg: "",
			emojiId
		};
		const ips = body.uploadIps;
		body.uploadPorts;
		if (ips.length === 0) return {
			retCode: -1,
			errMsg: "no upload server returned",
			emojiId
		};
		const server = [];
		for (const [index, ip] of ips.entries()) server.push(`${uint32ToIPV4Addr(ip)}:15000`);
		await new HighwayHttpSession({
			uin: selfInfo.uin,
			cmd: 9,
			readable: createReadStream(emojiPath, { highWaterMark: 1024 * 1024 }),
			sum: md5,
			size: stat.size,
			ticket: body.uKey,
			ext: Buffer.alloc(0),
			server
		}).upload();
		return {
			retCode: 0,
			errMsg: "",
			emojiId
		};
	}
	async deleteCustomFace(emojiIds) {
		return await this.ctx.qqProtocol.deleteFavEmojis(emojiIds);
	}
	async translatePtt2Text(msgId, peer, senderUin, voiceMsgElement) {
		const ptt = voiceMsgElement.pttElement;
		const result = new Promise((resolve, reject) => {
			const dispose = this.ctx.on("nt/ptt-trans-result", (input) => {
				if (input.msgId !== msgId) return;
				clearTimeout(timer);
				dispose();
				resolve(input.text);
			});
			const timer = setTimeout(() => {
				dispose();
				reject(/* @__PURE__ */ new Error("translatePtt2Text 超时（30s 未收到转写结果）"));
			}, 3e4);
		});
		if (peer.chatType === ChatType.Group) await this.ctx.qqProtocol.pttTransGroupReq({
			msgUid: BigInt(msgId),
			senderUin,
			groupUin: +peer.peerUid,
			voiceMd5Hex: ptt.md5HexStr,
			voiceFileId: ptt.fileUuid
		});
		else await this.ctx.qqProtocol.pttTransC2CReq({
			msgUid: BigInt(msgId),
			senderUin,
			receiverUin: +selfInfo.uin,
			voiceMd5Hex: ptt.md5HexStr,
			voiceFileId: ptt.fileUuid
		});
		return result;
	}
	async setPrivateInputStatus(toUid, eventType) {
		const { body } = await this.ctx.qqProtocol.setInputStatus(toUid, eventType);
		return body;
	}
	async getPins() {
		return await this.ctx.qqProtocol.fetchPins();
	}
	async sendPrivateFileMessage(opts) {
		return await this.ctx.qqProtocol.sendC2CFileMessage(opts);
	}
	async sendGroupFileMessage(groupCode, fileId) {
		const random = Math.floor(Math.random() * 4294967295);
		const res = await this.ctx.qqProtocol.feedGroupFile(groupCode, fileId, random);
		return {
			...res.feedsInfoRsp,
			retCode: Number(res.feedsInfoRsp.retCode),
			feedsResultList: res.feedsInfoRsp.feedsResultList.map((e) => ({
				...e,
				retCode: Number(e.retCode)
			}))
		};
	}
	async getLatestMsgSeq(peer) {
		if (peer.chatType === ChatType.Group) {
			const { info } = await this.ctx.qqProtocol.fetchGroupExtra(+peer.peerUid);
			return info.results.latestMessageSeq;
		} else {
			const { seq1, seq2 } = await this.ctx.qqProtocol.getFriendLatestSequence(peer.peerUid);
			return Math.max(seq1, seq2);
		}
	}
	async getForwardedMsgs(resId) {
		const { pbItemList } = await this.ctx.qqProtocol.getMultiMsg(resId);
		return { msgList: filterNullable((pbItemList.find((x) => x.fileName === "MultiMsg") ?? pbItemList[0]).buffer.msg.map((e) => convertToRawMessage(e))) };
	}
	async uploadForwardMsgs(peerUid, isGroup, items) {
		return (await this.ctx.qqProtocol.uploadForward(peerUid, isGroup, items)).result.resId;
	}
	async getRecommendFace(word) {
		return await this.ctx.qqProtocol.pullPics(word);
	}
};
