//#region src/webui/BE/routes/login.ts
function createLoginRoutes(ctx) {
	const router = new Hono();
	router.get("/login-qrcode", async (c) => {
		try {
			const data = await ctx.ntLoginApi.getLoginQrCode();
			return c.json({
				success: true,
				data
			});
		} catch (e) {
			return c.json({
				success: false,
				message: "获取登录二维码失败",
				error: e
			}, 500);
		}
	});
	router.get("/quick-login-list", async (c) => {
		try {
			const data = await ctx.ntLoginApi.getQuickLoginList();
			return c.json({
				success: true,
				data
			});
		} catch (e) {
			return c.json({
				success: false,
				message: "获取快速登录账号列表失败",
				error: e
			}, 500);
		}
	});
	router.post("/quick-login", async (c) => {
		const { uin } = await c.req.json();
		if (!uin) return c.json({
			success: false,
			message: "没有选择QQ号"
		}, 400);
		try {
			await ctx.qqProtocol.quickLogin(String(uin));
			return c.json({
				success: true,
				data: {
					result: "0",
					loginErrorInfo: { errMsg: "" }
				}
			});
		} catch (e) {
			return c.json({
				success: false,
				message: e.message || "快速登录失败",
				data: {
					result: "-1",
					loginErrorInfo: { errMsg: e.message || "快速登录失败" }
				}
			}, 500);
		}
	});
	router.post("/logout", async (c) => {
		try {
			await ctx.qqProtocol.logout();
			return c.json({ success: true });
		} catch (e) {
			return c.json({
				success: false,
				message: e.message || "退出登录失败"
			}, 500);
		}
	});
	router.get("/login-info", (c) => {
		let webui;
		if (selfInfo.online && selfInfo.uin) try {
			const p = path.join(DATA_DIR, `config_${selfInfo.uin}.json`);
			if (existsSync(p)) {
				const cfg = import_dist.default.parse(readFileSync(p, "utf-8"));
				if (cfg?.webui) webui = {
					enable: cfg.webui.enable !== false,
					host: cfg.webui.host ?? "",
					port: Number(cfg.webui.port) || 0
				};
			}
		} catch {}
		return c.json({
			success: true,
			data: {
				...selfInfo,
				webui
			}
		});
	});
	return router;
}
