//#region src/webui/BE/routes/logs.ts
function createLogsRoutes(ctx) {
	const router = new Hono();
	router.get("/logs/stream", async (c) => {
		return streamSSE(c, async (stream) => {
			stream.writeSSE({
				data: "{}",
				event: "connected"
			});
			for (const record of getLogCache()) stream.writeSSE({ data: JSON.stringify(record) });
			const dispose = ctx.on("llob/log", (record) => {
				stream.writeSSE({ data: JSON.stringify(record) });
			});
			stream.onAbort(() => {
				dispose();
			});
			return new Promise((resolve) => {
				stream.onAbort(resolve);
			});
		});
	});
	return router;
}
