//#region src/webui/BE/routes/webqq/index.ts
function createWebQQRoutes(ctx, options) {
	const router = new Hono();
	const { uploadDir, sseClients, createPicElement } = options;
	router.route("/", createMessagesRoutes(ctx, createPicElement));
	router.route("/", createUploadRoutes(ctx, uploadDir));
	router.route("/", createProxyRoutes(ctx));
	router.route("/", createMembersRoutes(ctx));
	router.route("/", createNotificationRoutes(ctx));
	router.route("/", createChatsRoutes(ctx));
	router.route("/", createActionsRoutes(ctx));
	router.get("/events", async (c) => {
		return streamSSE(c, async (stream) => {
			stream.writeSSE({
				data: "{}",
				event: "connected"
			});
			sseClients.add(stream);
			stream.onAbort(() => {
				sseClients.delete(stream);
			});
			return new Promise((resolve) => {
				stream.onAbort(resolve);
			});
		});
	});
	return router;
}
//#endregion
//#region src/webui/BE/routes/email.ts
function createEmailRoutes(ctx) {
	const router = new Hono();
	const getEmail = () => ctx.get("emailNotification");
	router.get("/config", async (c) => {
		try {
			const emailService = getEmail();
			if (!emailService) return c.json({
				success: false,
				message: "邮件服务未初始化，请等待登录完成"
			}, 503);
			const config = emailService.getConfigManager().getConfig();
			const maskedConfig = {
				...config,
				smtp: {
					...config.smtp,
					auth: {
						...config.smtp.auth,
						pass: config.smtp.auth.pass ? "********" : ""
					}
				}
			};
			return c.json({
				success: true,
				data: maskedConfig
			});
		} catch (error) {
			ctx.logger?.error("[EmailAPI] Failed to get email config:", error);
			return c.json({
				success: false,
				message: error.message || "获取邮件配置失败"
			}, 500);
		}
	});
	router.post("/config", async (c) => {
		try {
			const emailService = getEmail();
			if (!emailService) return c.json({
				success: false,
				message: "邮件服务未初始化，请等待登录完成"
			}, 503);
			const emailConfig = await c.req.json();
			if (!emailConfig) return c.json({
				success: false,
				message: "邮件配置不能为空"
			}, 400);
			const configManager = emailService.getConfigManager();
			const currentConfig = configManager.getConfig();
			if (emailConfig.smtp.auth.pass === "********" || emailConfig.smtp.auth.pass === "") emailConfig.smtp.auth.pass = currentConfig.smtp.auth.pass;
			const validation = configManager.validateConfig(emailConfig);
			if (!validation.valid) return c.json({
				success: false,
				message: `配置验证失败：${validation.errors.join(", ")}`
			}, 400);
			await configManager.saveConfig(emailConfig);
			ctx.parallel("llbot/email-config-updated", emailConfig);
			return c.json({
				success: true,
				message: "邮件配置保存成功"
			});
		} catch (error) {
			ctx.logger?.error("[EmailAPI] Failed to save email config:", error);
			return c.json({
				success: false,
				message: error.message || "保存邮件配置失败"
			}, 500);
		}
	});
	router.post("/test", async (c) => {
		try {
			const emailService = getEmail();
			if (!emailService) return c.json({
				success: false,
				message: "邮件服务未初始化，请等待登录完成"
			}, 503);
			const { config: testConfig } = await c.req.json();
			let emailConfig;
			if (testConfig) {
				emailConfig = testConfig;
				const currentConfig = emailService.getConfigManager().getConfig();
				if (emailConfig.smtp.auth.pass === "********" || emailConfig.smtp.auth.pass === "") emailConfig.smtp.auth.pass = currentConfig.smtp.auth.pass;
			} else emailConfig = emailService.getConfigManager().getConfig();
			const configManager = emailService.getConfigManager();
			const validation = configManager.validateConfig(emailConfig);
			if (!validation.valid) return c.json({
				success: false,
				message: validation.errors.join(", ")
			}, 400);
			const tempConfigManager = new configManager.constructor("", ctx.logger);
			tempConfigManager["config"] = emailConfig;
			const result = await new (emailService.getEmailService()).constructor(tempConfigManager, ctx.logger).sendTestEmail();
			if (result.success) return c.json({
				success: true,
				message: "测试邮件发送成功",
				messageId: result.messageId
			});
			else return c.json({
				success: false,
				message: result.error || "测试邮件发送失败"
			}, 400);
		} catch (error) {
			ctx.logger?.error("[EmailAPI] Failed to send test email:", error);
			return c.json({
				success: false,
				message: error.message || "测试邮件发送失败"
			}, 500);
		}
	});
	return router;
}
